  function repeatDecline(context){var latest=context.latest,previous=context.previous;if(!latest||!previous||latest.repeatSalesPct==null||previous.repeatSalesPct==null)return null;var drop=amount(previous.repeatSalesPct)-amount(latest.repeatSalesPct);if(drop<10)return null;return alert('REPEAT_CUSTOMER_DECLINE','MONTHLY',{now:context.now,priority:drop>=20?'HIGH':'MEDIUM',summary:'Comparable repeat-customer sales share fell by '+percent(drop)+' (percentage points).',reason:'Existing Stage 7A customer identity evidence shows '+percent(latest.repeatSalesPct)+' versus '+percent(previous.repeatSalesPct)+' in the prior complete month.',metricValues:[formatMetric('Latest repeat share',latest.repeatSalesPct,'percent'),formatMetric('Previous repeat share',previous.repeatSalesPct,'percent'),formatMetric('Decline',drop,'percent')],financialExposure:round(amount(latest.sales)*drop/100),dataConfidence:confidence(context,{history:true})});}
  function unidentifiedSales(context){var current=context.current;if(!current.sales||current.identifiedSalesPct==null)return null;var share=100-current.identifiedSalesPct;if(share<40)return null;return alert('UNIDENTIFIED_SALES_EXPOSURE','CURRENT_MONTH',{now:context.now,priority:share>=70?'HIGH':'MEDIUM',summary:percent(share)+' of current recorded sales lack reliable customer identity.',reason:'This uses Stage 7A customer matching only; no new fuzzy identity matching is introduced.',metricValues:[formatMetric('Unidentified sales',current.sales*share/100),formatMetric('Current sales',current.sales),formatMetric('Unidentified share',share,'percent')],financialExposure:round(current.sales*share/100),dataConfidence:confidence(context,{current:true})});}
  function qualityAlerts(context){var out=[];if(context.model.forecasts.sales.trend==null&&(context.model.salesEarliest!=null||context.current.sales>0))out.push(alert('INSUFFICIENT_SALES_HISTORY','TREND',{now:context.now,priority:'INFORMATIONAL',summary:'Recent-month trend forecast is unavailable because three complete comparable sales months are not covered.',reason:'No sales estimate is manufactured; current run-rate, if shown, remains separately labelled.',metricValues:[formatMetric('Complete comparable months',context.model.forecasts.sales.trend==null?0:3,'number')],financialExposure:null,dataConfidence:'LIMITED DATA'}));if(context.current.transactions&&context.current.grossProfit==null)out.push(alert('INCOMPLETE_FIFO_EVIDENCE','CURRENT_MONTH',{now:context.now,priority:'INFORMATIONAL',summary:'Current factual gross profit is unavailable because complete FIFO cost evidence is missing.',reason:'The application does not substitute catalogue, average or latest purchase cost.',metricValues:[formatMetric('Transactions with sales evidence',context.current.transactions,'number')],financialExposure:null,dataConfidence:'LIMITED DATA'}));if(context.current.sales>0&&!context.current.cashCount)out.push(alert('CASH_COVERAGE_UNAVAILABLE','CURRENT_MONTH',{now:context.now,priority:'INFORMATIONAL',summary:'Current sales exist but no active cashLog movement covers the current period.',reason:'Sales are not interpreted as cash collection.',metricValues:[formatMetric('Current sales',context.current.sales)],financialExposure:null,dataConfidence:'LIMITED DATA'}));return out;}
