  function acknowledge(alertKey){try{updateState(alertKey,{status:'ACKNOWLEDGED',acknowledgedAt:new Date().toISOString(),acknowledgedBy:identity().id},'ACKNOWLEDGED');notify('Alert acknowledged as management metadata.');if(typeof render==='function')render();return true;}catch(error){notify(error.message||String(error),'err');return false;}}
