  function viewHTML(){if(!ownerAdmin())return '<section class="card"><h3>Management Alerts &amp; Priorities</h3><p class="muted">This Owner/Admin planning view is restricted.</p></section>';var result=calculate(database()),visible=visibleAlerts(result);runtime.context=result.context;runtime.alerts=result.active;runtime.lastCalculatedAt=new Date(result.context.now).toISOString();return '<section id="managementAlertsLab" data-stage="7C" data-version="'+VERSION+'" data-build="'+BUILD+'"><style id="managementAlertsStyles">#managementAlertsLab{min-width:0}#managementAlertsLab .ma-card{margin-bottom:12px}#managementAlertsLab .ma-counts,#managementAlertsLab .ma-top,#managementAlertsLab .ma-queue{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}#managementAlertsLab .ma-count{padding:10px;border:1px solid #334155;border-radius:10px;background:#142238}#managementAlertsLab .ma-count span{font-size:11px;font-weight:800;letter-spacing:.04em;color:#cbd5e1}#managementAlertsLab .ma-count b{display:block;font-size:24px;margin-top:4px}#managementAlertsLab .ma-alert{min-width:0;margin:0;border-left:4px solid #64748b}#managementAlertsLab .ma-alert[data-priority="CRITICAL"]{border-left-color:#dc2626}#managementAlertsLab .ma-alert[data-priority="HIGH"]{border-left-color:#ea580c}#managementAlertsLab .ma-alert[data-priority="MEDIUM"]{border-left-color:#ca8a04}#managementAlertsLab .ma-alert[data-priority="WATCH"]{border-left-color:#0284c7}#managementAlertsLab .ma-alert-head,#managementAlertsLab .ma-actions,#managementAlertsLab .ma-snooze{display:flex;gap:7px;align-items:center;flex-wrap:wrap}#managementAlertsLab .ma-category,#managementAlertsLab .ma-state{font-size:12px;color:#cbd5e1}#managementAlertsLab .ma-state{margin-left:auto}.ma-priority{font-size:11px;font-weight:900;border-radius:99px;padding:4px 8px;background:#334155;color:#e2e8f0}.ma-critical{background:#7f1d1d;color:#fecaca}.ma-high{background:#9a3412;color:#fed7aa}.ma-medium{background:#854d0e;color:#fde68a}.ma-watch{background:#0c4a6e;color:#bae6fd}.ma-informational{background:#334155;color:#e2e8f0}.ma-forecast{color:#fbbf24}.ma-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px 16px;margin:10px 0}.ma-metric{display:flex;justify-content:space-between;gap:8px;border-bottom:1px dotted #334155;padding:3px 0}.ma-metric span{color:#cbd5e1}.ma-filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.ma-filters label{display:grid;gap:5px;font-size:12px;font-weight:700}.ma-filters select,#managementAlertsLab input,#managementAlertsLab textarea{width:100%;box-sizing:border-box;background:#081221;color:#f8fafc;border:1px solid #475569}.ma-snooze input{max-width:150px}.ma-alert textarea{min-height:55px;margin-top:9px}.ma-change{display:flex;gap:10px;flex-wrap:wrap;color:#cbd5e1}.ma-change span{padding:6px 9px;border:1px solid #334155;border-radius:8px}.ma-rule-list details{border-top:1px solid #334155;padding:9px 0}.ma-rule-list p{margin:6px 0}@media(max-width:900px){#managementAlertsLab .ma-counts,#managementAlertsLab .ma-top,#managementAlertsLab .ma-queue{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){#managementAlertsLab .ma-counts,#managementAlertsLab .ma-top,#managementAlertsLab .ma-queue,#managementAlertsLab .ma-filters{grid-template-columns:1fr}.ma-metrics{grid-template-columns:1fr}.ma-state{margin-left:0!important}.ma-actions .btn,.ma-snooze .btn{flex:1}}</style><section class="card ma-card"><div class="row" style="justify-content:space-between;align-items:flex-start"><div><h2 style="margin:0">Management Alerts &amp; Priorities</h2><p class="muted">Stage 7C · explainable prioritisation from actual business evidence, active targets and transparent forecasts. It never posts business transactions.</p></div><span class="pill">r65 · recalculated '+esc(new Date(result.context.now).toLocaleString())+'</span></div><div class="notice">Forecast-based alerts are labelled and are not actual breaches. Hypothetical scenarios do not trigger alerts. A negative <b>Others</b> wallet alone is not an alert.</div></section><section class="card ma-card"><h3>Management Attention Queue</h3><div class="ma-counts">'+countCards(result.active)+'</div><p class="muted">Last recalculated '+esc(runtime.lastCalculatedAt)+' · current calendar-month analytical window.</p></section><section class="card ma-card"><h3>Top Management Priorities</h3><div class="ma-top">'+(result.active.filter(function(item){return !item.snoozed;}).slice(0,5).map(function(item){return alertCard(item,true);}).join('')||'<p class="muted">No active management alerts met a rule threshold.</p>')+'</div></section>'+filterHTML(result)+'<section class="card ma-card"><h3>'+esc(runtime.filters.status==='RESOLVED'?'Recently Resolved (derived from current evidence)':'Management Attention Queue')+'</h3><div class="ma-queue">'+(visible.map(function(item){return alertCard(item,false);}).join('')||'<p class="muted">No alerts match the selected filters.</p>')+'</div></section>'+whatChanged(result.context,result)+ruleRegistryHTML()+'</section>';}
