  function installRouting(){setTitle();addNavigation();var baseNav=window.nav;if(typeof baseNav==='function'&&!baseNav.__managementAlertsRoute){var wrappedNav=function(view){if(String(view||'')==='management-alerts'){if(!ownerAdmin()){notify('Management Alerts & Priorities is restricted to Owner/Admin.','err');return baseNav.call(this,'pos');}try{currentView='management-alerts';}catch(_){}return window.render();}return baseNav.apply(this,arguments);};wrappedNav.__managementAlertsRoute=true;window.nav=wrappedNav;}var baseRender=window.render;if(typeof baseRender==='function'&&!baseRender.__managementAlertsRoute){var wrappedRender=function(){var view='';try{view=String(currentView||'');}catch(_){try{view=String(window.currentView||'');}catch(_2){}}return view==='management-alerts'?renderView(baseRender):baseRender.apply(this,arguments);};wrappedRender.__managementAlertsRoute=true;window.render=wrappedRender;}return true;}

